/// `Validator.isPhone(value, country)`: [callingCode] is the country calling
/// code (`1`, `44`, `+90`); [value] must be a valid `Phone` under it. A
/// [callingCode] that is not one throws, so a region name never validates every
/// number false.
bool cruftfreeValidatorIsPhoneIn(String value, String callingCode) {
  final code = RegExp(r'^\+?([1-9]\d{0,2})$').firstMatch(callingCode);
  if (code == null) {
    throw ArgumentError.value(callingCode, 'country', "Validator.isPhone country must be a country calling code such as '1', '44' or '+90'");
  }
  return cruftfreeValidatorIsPhone(value) && value.replaceFirst(RegExp(r'^\+'), '').startsWith(code.group(1)!);
}

/// `Validator.isDate(value, format)`: [value] written exactly as [pattern] says.
bool cruftfreeValidatorIsDateWith(String value, String pattern) => cruftfreeDateMatchesPattern(value, pattern);

final RegExp _cruftfreeCardSeparators = RegExp('[ \\-]', unicode: true);

final RegExp _cruftfreeCardDigits = RegExp('^(?:[0-9]{12,19})\$', unicode: true);

final RegExp _cruftfreeIsoDate = RegExp('^(?:([0-9]{4})-([0-9]{2})-([0-9]{2})(?:[ T]([0-9]{2}):([0-9]{2})(?::([0-9]{2})(?:\\.[0-9]{1,9})?)?(?:Z|[+\\-](?:[0-1][0-9]|2[0-3]):?[0-5][0-9])?)?)\$', unicode: true);

final RegExp _cruftfreeSlashDate = RegExp('^(?:([0-9]{1,2})/([0-9]{1,2})/([0-9]{4}))\$', unicode: true);

final RegExp _cruftfreeDashDate = RegExp('^(?:([0-9]{1,2})-([0-9]{1,2})-([0-9]{4}))\$', unicode: true);

/// Days per month, January first, in a common year.
const List<int> _cruftfreeDaysInMonth = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];

/// `Validator.isCreditCard`: ASCII spaces and hyphens removed, 12-19 ASCII
/// digits whose Luhn sum is a multiple of 10. The card brand is not checked.
bool cruftfreeValidatorIsCreditCard(String? value) {
  if (value == null) return false;
  final digits = value.replaceAll(_cruftfreeCardSeparators, '');
  if (!_cruftfreeCardDigits.hasMatch(digits)) return false;
  var total = 0;
  for (var position = 0; position < digits.length; position++) {
    var digit = digits.codeUnitAt(digits.length - 1 - position) - 0x30;
    if (position.isOdd) {
      digit *= 2;
      if (digit > 9) digit -= 9;
    }
    total += digit;
  }
  return total % 10 == 0;
}

/// Whether [year]-[month]-[day] is a day of the Gregorian calendar, from year
/// 1.
bool _cruftfreeIsCalendarDay(int year, int month, int day) {
  if (year < 1 || month < 1 || month > _cruftfreeDaysInMonth.length || day < 1) {
    return false;
  }
  final leap = year % 4 == 0 && (year % 100 != 0 || year % 400 == 0);
  return day <= _cruftfreeDaysInMonth[month - 1] + (month == 2 && leap ? 1 : 0);
}

/// `Validator.isDate(value)`: [value] is, whole, an ISO `yyyy-MM-dd` date
/// with an optional time (`T` or a space, `HH:mm`, optional `:ss` and
/// fraction, optional `Z` or offset), a `d/M/yyyy` or `M/d/yyyy` date, or a
/// `d-M-yyyy` date, every component checked against the calendar.
bool cruftfreeValidatorIsDate(String? value) {
  if (value == null) return false;
  final iso = _cruftfreeIsoDate.firstMatch(value);
  if (iso != null) {
    final year = int.parse(iso.group(1)!);
    final month = int.parse(iso.group(2)!);
    final day = int.parse(iso.group(3)!);
    if (!_cruftfreeIsCalendarDay(year, month, day)) return false;
    final hour = iso.group(4);
    if (hour == null) return true;
    final second = iso.group(6);
    return int.parse(hour) <= 23 && int.parse(iso.group(5)!) <= 59 && (second == null || int.parse(second) <= 59);
  }
  final slash = _cruftfreeSlashDate.firstMatch(value);
  if (slash != null) {
    final first = int.parse(slash.group(1)!);
    final second = int.parse(slash.group(2)!);
    final year = int.parse(slash.group(3)!);
    return _cruftfreeIsCalendarDay(year, second, first) || _cruftfreeIsCalendarDay(year, first, second);
  }
  final dash = _cruftfreeDashDate.firstMatch(value);
  if (dash != null) {
    return _cruftfreeIsCalendarDay(int.parse(dash.group(3)!), int.parse(dash.group(2)!), int.parse(dash.group(1)!));
  }
  return false;
}

/// `Validator.isJson`: [value] is one RFC 8259 JSON text, any value, using
/// `dart:convert`'s strict decoder as the oracle.
bool cruftfreeValidatorIsJson(String? value) {
  if (value == null) return false;
  try {
    jsonDecode(value);
    return true;
  } on FormatException {
    return false;
  }
}

/// `Validator.isEmpty`: [value] is absent, or a text, list or map with
/// nothing in it. A number or a boolean is never empty.
bool cruftfreeValidatorIsEmpty(Object? value) {
  if (value == null) return true;
  if (value is String) return value.isEmpty;
  if (value is Iterable) return value.isEmpty;
  if (value is Map) return value.isEmpty;
  return false;
}

/// Whether [value] (an ISO-8601 date-time string -- this target represents
/// the DSL `DateTime` type as text) is strictly after the current instant.
bool cruftfreeValidatorIsFutureDate(String value) {
  return cruftfreeParseTemporal(value).isAfter(DateTime.now().toUtc());
}

/// Whether [value] (an ISO-8601 date-time string) is strictly before the
/// current instant.
bool cruftfreeValidatorIsPastDate(String value) {
  return cruftfreeParseTemporal(value).isBefore(DateTime.now().toUtc());
}

/// `low <= value <= high` for numbers, strings or any other comparable values.
bool cruftfreeValidatorInRange<T extends Comparable<Object>>(T value, T low, T high) => low.compareTo(value) <= 0 && value.compareTo(high) <= 0;

/// `low <= length <= high` for a string (in code points, as on every target), a list or a map.
bool cruftfreeValidatorLengthBetween(Object value, int low, int high) {
  final length = switch (value) {
    String text => text.runes.length,
    Iterable<Object?> items => items.length,
    Map<Object?, Object?> entries => entries.length,
    _ => throw ArgumentError.value(value, 'value', 'Validator length checks take a string, a list or a map'),
  };
  return low <= length && length <= high;
}

/// Whether [value] matches [pattern] over its ENTIRE length. Delegates to
/// `cruftfreeFullMatch` in `builtins/text.dart` (see that file's module
/// docstring) rather than re-implementing full-match semantics here, so
/// there is exactly one definition of "matches" in this package.
bool cruftfreeValidatorMatches(String value, RegExp pattern) => cruftfreeFullMatch(value, pattern);

/// Structural validation of a `{datasetName: records}` collection: each
/// dataset must map to a non-empty list. Exact port of the Python
/// reference backend's `_validator_validate_datasets` helper.
Map<String, Object?> cruftfreeValidatorValidateDatasets(Object? datasets) {
  if (datasets is! Map) {
    return {
      'isValid': false,
      'errors': const ['datasets must be a map'],
    };
  }
  final errors = <String>[];
  datasets.forEach((name, records) {
    if (records is! List) {
      errors.add("Dataset '$name' must be a list, got ${records.runtimeType}");
    } else if (records.isEmpty) {
      errors.add("Dataset '$name' is empty");
    }
  });
  return {'isValid': errors.isEmpty, 'errors': errors};
}
